detail.example:
# 어휘 크기(Vocabulary) 예시: Python 3에서 실행 가능한 코드
vocab = {"hello": 0, "world": 1, "!": 2}
print(len(vocab))

# 탐욕적 디코딩 예시: Python 3에서 실행 가능한 코드
probs = {"A": 0.2, "B": 0.7, "C": 0.1}
print(max(probs, key=probs.get))

# 반복 패널티 예시: Python 3에서 실행 가능한 코드
seen = {"안녕"}
scores = {"안녕": 0.9, "반가워": 0.7}
for tok in seen:
    scores[tok] *= 0.5
print(max(scores, key=scores.get))

# 시맨틱 검색 예시: Python 3에서 실행 가능한 코드
query = {"warm", "coat"}
doc = {"winter", "coat"}
score = len(query & doc)
print(score)

# 함수 호출(Function Calling) 예시: Python 3에서 실행 가능한 코드
call = {"name": "add_event", "args": {"title": "회의"}}
print(call["name"], call["args"]["title"])

# 멀티 에이전트 예시: Python 3에서 실행 가능한 코드
agents = {"planner": "계획", "worker": "실행", "reviewer": "검토"}
print(list(agents))

# KV 캐시 예시: Python 3에서 실행 가능한 코드
cache = {}
cache[0] = {"key": "k0", "value": "v0"}
print(cache[0]["key"])

# 모델 서빙 예시: Python 3에서 실행 가능한 코드
request = {"text": "안녕"}
response = {"prediction": "인사"}
print(response["prediction"])

# 멀티모달 모델 예시: Python 3에서 실행 가능한 코드
inputs = {"text": "고양이", "image_tags": ["cat", "sofa"]}
print(inputs["text"] in ["고양이", "cat"])

# 평가 벤치마크(MMLU/HumanEval) 예시: Python 3에서 실행 가능한 코드
scores = {"MMLU": 0.78, "HumanEval": 0.65}
print(sum(scores.values()) / len(scores))

# 해석 가능성(Interpretability) 예시: Python 3에서 실행 가능한 코드
features = {"증상A": 0.6, "증상B": 0.2}
print(max(features, key=features.get))

# 모델 컨텍스트 프로토콜(MCP) 예시: Python 3에서 실행 가능한 코드
tool = {"name": "search", "schema": {"query": "string"}}
print(tool["schema"]["query"])
